from datetime import datetime, timezone
from types import SimpleNamespace
from hypothesis import given, strategies as st
from enoch_control_plane.control_plane.alerts import queue_alert_findings

@given(st.booleans(), st.booleans(), st.text(max_size=40), st.text(max_size=40))
def test_queue_alert_findings_never_alerts_when_intentional_hold(paused, maintenance, project_id, run_id):
    if not (paused or maintenance):
        paused = True
    status = SimpleNamespace(flags=SimpleNamespace(queue_paused=paused, maintenance_mode=maintenance), config=SimpleNamespace(live_dispatch_enabled=True), conflicts=[], active_items=[{'project_id': project_id, 'current_run_id': run_id, 'updated_at': datetime(2000,1,1,tzinfo=timezone.utc)}], warnings=[], source_freshness={}, observations={})
    assert queue_alert_findings(status, hang_after_sec=1) == []
